import sys

# Increase recursion depth to handle deep nesting of '^' or unary minus
sys.setrecursionlimit(20000)

def calc(expr: str) -> int | str:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append(('OP', c))
            i += 1
        else:
            i += 1

    pos = 0
    num_tokens = len(tokens)

    def peek():
        if pos < num_tokens:
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        pos += 1

    def parse_expr():
        return parse_additive()

    def parse_additive():
        left = parse_multiplicative()
        while True:
            t = peek()
            if t and t[1] in ('+', '-'):
                op = t[1]
                advance()
                right = parse_multiplicative()
                if right == "error" or left == "error":
                    return "error"
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_multiplicative():
        left = parse_unary()
        while True:
            t = peek()
            if t and t[1] in ('*', '/', '%'):
                op = t[1]
                advance()
                right = parse_unary()
                if right == "error" or left == "error":
                    return "error"
                if op == '*':
                    left = left * right
                elif op == '/':
                    if right == 0:
                        return "error"
                    # Truncating division towards zero
                    if (left > 0) != (right > 0) and left % right != 0:
                        left = (left // right) + 1
                    else:
                        left = left // right
                elif op == '%':
                    # a % b = a - b * trunc(a/b)
                    if right == 0:
                        return "error"
                    a = left
                    b = right
                    if (a > 0) != (b > 0) and a % b != 0:
                        q = (a // b) + 1
                    else:
                        q = a // b
                    left = a - b * q
            else:
                break
        return left

    def parse_unary():
        sign = 1
        t = peek()
        while t and t[1] == '-':
            sign = -sign
            advance()
            t = peek()
        val = parse_power()
        if val == "error":
            return "error"
        return sign * val

    def parse_power():
        base = parse_primary()
        if base == "error":
            return "error"
        t = peek()
        if t and t[1] == '^':
            advance()
            exp = parse_power()
            if exp == "error":
                return "error"
            if exp < 0:
                return "error"
            return base ** exp
        return base

    def parse_primary():
        t = peek()
        if t is None:
            return "error"
        if t[1] == '(':
            advance()
            val = parse_expr()
            if val == "error":
                return "error"
            t2 = peek()
            if t2 and t2[1] == ')':
                advance()
                return val
            else:
                return "error"
        elif t[0] == 'NUM':
            advance()
            return t[1]
        else:
            return "error"

    try:
        result = parse_expr()
        return result
    except Exception:
        return "error"
